window.RP_SESSION={"id":"S-0fb333df806c","messages":[{"id":"RP-0057283","time":"2026-02-27T09:33:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오늘도 좋은 아침! 하품 내뱉고 가만히 길드 앞 잔디밭에 앉아있었습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057284","time":"2026-02-27T09:33:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오늘 무언가 재미있는 일이 생길까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057285","time":"2026-02-27T09:34:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······. 있다보면 알게 될겁니다. 가만히 앉아 멍하게 앞만 바라봅니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057286","time":"2026-02-27T09:36:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"하품이 나와서 하품을 내뱉고···. 오래간만에 책을 펼칩니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057287","time":"2026-02-27T09:36:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"최근에는 길드원들이 좋아하는 주류를 만들어보고 싶다는 생각이 많이 들었거든요","characters":["P-b6d81d634c6e"]},{"id":"RP-0057288","time":"2026-02-27T09:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b6d81d634c6e"]},{"id":"RP-0057289","time":"2026-02-27T09:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 1 = 1\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0057290","time":"2026-02-27T09:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"책장을 넘기며···. 음. 빤히 바라보지만.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057291","time":"2026-02-27T09:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"········· 책을 잘못 집었습니다···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057292","time":"2026-02-27T09:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아니, 애초에 책도 아닙니다······. 노트네요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0057293","time":"2026-02-27T09:38:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"절망. 마리우스는 자신의 투구를 잡고 소리 없는 비명을 지릅니다.","characters":["P-b6d81d634c6e"]}]};
